// Some portions generated by Claude
// @ts-check
const { test, expect } = require('@playwright/test');
const {
    deleteRepository,
    memoryRepositoryConfiguration,
    repositoryPageUrl,
    serverBaseUrl,
    uniqueRepositoryId,
    waitForRoute
} = require('./workbench-test-helpers.js');

// The Graph page's filters: the filters follow what is still selectable, numbers filter by range, active filters are
// chips that remove themselves, a filter can need all of its values, and a search opens the filters that contain a
// matching value.
const REPOSITORY_ID = uniqueRepositoryId('graph-filters');
const DATA = `
@prefix ex: <http://example.org/filters/> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .
ex:alice a ex:Person, ex:Manager ; rdfs:label "Alice" ; ex:age 39 ; ex:worksFor ex:acme .
ex:bob a ex:Person ; rdfs:label "Bob" ; ex:age 34 ; ex:worksFor ex:acme .
ex:carol a ex:Person, ex:Manager ; rdfs:label "Carol" ; ex:age 46 ; ex:worksFor ex:globex .
ex:dave a ex:Person ; rdfs:label "Dave" ; ex:age 29 .
ex:acme a ex:Organization ; rdfs:label "Acme" ; ex:founded "1999-04-01"^^xsd:date .
ex:globex a ex:Organization ; rdfs:label "Globex" ; ex:founded "2005-10-10"^^xsd:date .
`;

test.beforeAll(async ({ request }) => {
    const repositoryUrl = `${serverBaseUrl()}/repositories/${REPOSITORY_ID}`;
    const created = await request.put(repositoryUrl, {
        headers: { 'Content-Type': 'text/turtle' },
        data: memoryRepositoryConfiguration(REPOSITORY_ID, 'Graph filters')
    });
    expect([200, 201, 204]).toContain(created.status());
    const loaded = await request.post(`${repositoryUrl}/statements`, {
        headers: { 'Content-Type': 'text/turtle' },
        data: DATA
    });
    expect([200, 204]).toContain(loaded.status());
});

test.afterAll(async ({ request }) => {
    await deleteRepository(request, serverBaseUrl(), REPOSITORY_ID);
});

async function openFilters(page) {
    await page.setViewportSize({ width: 1440, height: 900 });
    await page.goto(repositoryPageUrl(REPOSITORY_ID, 'graph'));
    await waitForRoute(page, 'graph');
    const explorer = page.locator('.graph-explorer');
    await explorer.getByRole('button', { name: 'Load 100 statements' }).click();
    await expect(explorer.locator('.graph-node')).toHaveCount(6, { timeout: 30000 });
    await explorer.getByRole('button', { name: /Filter graph nodes/ }).click();
    return explorer.locator('#graph-filter-sidebar');
}

const filterNames = (panel) => panel.locator('.filter-facet summary strong');

test('choosing a type leaves only the filters that apply to it', async ({ page }) => {
    const panel = await openFilters(page);
    await expect(filterNames(panel)).toHaveText(['Type', 'age', 'works for', 'founded']);

    await panel.locator('.facet-value', { hasText: 'Person' }).click();
    await expect(panel.locator('.filter-sidebar-header small')).toHaveText('4 of 6 nodes match');
    await expect(filterNames(panel)).toHaveText(['Type', 'age', 'works for']);
    await expect(panel.locator('.filter-chips button')).toHaveText(['Person']);
});

test('numbers filter by range and active filters are chips that remove themselves', async ({ page }) => {
    const panel = await openFilters(page);
    await panel.locator('.filter-facet summary', { hasText: 'age' }).click();
    await panel.getByLabel('age from').fill('30');
    await panel.getByLabel('age to').fill('40');
    await expect(panel.locator('.filter-sidebar-header small')).toHaveText('2 of 6 nodes match');
    await expect(page.locator('.graph-explorer .graph-node.is-selected')).toHaveCount(2);

    const chip = panel.locator('.filter-chips button', { hasText: 'age: 30 – 40' });
    await chip.click();
    await expect(panel.locator('.filter-chips')).toHaveCount(0);
    await expect(page.locator('.graph-explorer .graph-node.is-selected')).toHaveCount(0);
});

test('a filter set to all values needs every one of them, and the active filters say "and"', async ({ page }) => {
    const panel = await openFilters(page);
    const matching = panel.locator('.filter-sidebar-header small');
    await panel.locator('.facet-value', { hasText: 'Person' }).click();
    await panel.locator('.facet-value', { hasText: 'Manager' }).click();
    await expect(matching).toHaveText('4 of 6 nodes match');
    await expect(panel.locator('.filter-chips .filter-chip-joiner')).toHaveText(['or']);

    const type = panel.locator('.filter-facet').filter({ has: page.locator('summary strong', { hasText: /^Type$/ }) });
    await type.locator('.facet-match-option', { hasText: 'All values' }).click();
    await expect(type.getByRole('radio', { name: 'All values' })).toBeChecked();
    await expect(matching).toHaveText('2 of 6 nodes match');
    await expect(page.locator('.graph-explorer .graph-node.is-selected')).toHaveCount(2);
    await expect(panel.locator('.filter-chips button')).toHaveText(['Manager', 'Person']);
    await expect(panel.locator('.filter-chips .filter-chip-joiner')).toHaveText(['and']);
    await expect(type.locator('.facet-selected-count')).toHaveText('2 · all');

    await type.locator('.facet-match-option', { hasText: 'Any value' }).click();
    await expect(matching).toHaveText('4 of 6 nodes match');
    await expect(panel.locator('.filter-chips .filter-chip-joiner')).toHaveText(['or']);
});

test('a search opens the filters that contain a matching value', async ({ page }) => {
    const panel = await openFilters(page);
    await panel.getByPlaceholder('Search filters and values').fill('globex');
    await expect(filterNames(panel)).toHaveText(['works for']);
    await expect(panel.locator('.facet-value', { hasText: 'Globex' })).toBeVisible();
});

// Filters list what the repository holds for the drawn nodes, not only what is loaded: people loaded with their names
// only can still be filtered by birthday. A write through the Workbench, in another tab too, brings new values in.
test('filters offer values that are not loaded, and a write in another tab brings new ones', async ({ page, context, request }) => {
    const id = uniqueRepositoryId('graph-filter-values');
    const repositoryUrl = `${serverBaseUrl()}/repositories/${id}`;
    const people = ['ann 1990-04-01', 'ben 1985-09-12', 'cat 2001-01-30', 'dan 1979-12-24', 'eve 1992-06-15'].map((entry) => {
        const [name, born] = entry.split(' ');
        return `ex:${name} a ex:Person ; rdfs:label "${name}" ; ex:birthDate "${born}"^^xsd:date .`;
    });
    expect([200, 201, 204]).toContain((await request.put(repositoryUrl, {
        headers: { 'Content-Type': 'text/turtle' }, data: memoryRepositoryConfiguration(id, 'Graph filter values')
    })).status());
    expect([200, 204]).toContain((await request.post(`${repositoryUrl}/statements`, {
        headers: { 'Content-Type': 'text/turtle' },
        data: '@prefix ex: <http://example.org/people/> .\n@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .\n'
            + '@prefix xsd: <http://www.w3.org/2001/XMLSchema#> .\n' + people.join('\n')
    })).status());
    try {
        await page.setViewportSize({ width: 1440, height: 900 });
        await page.goto(repositoryPageUrl(id, 'graph'));
        await waitForRoute(page, 'graph');
        const explorer = page.locator('.graph-explorer');
        await explorer.getByRole('button', { name: 'Query editor', exact: true }).click();
        await explorer.locator('#sparql').fill('CONSTRUCT { ?person <http://www.w3.org/2000/01/rdf-schema#label> ?name } '
            + 'WHERE { ?person a <http://example.org/people/Person> ; <http://www.w3.org/2000/01/rdf-schema#label> ?name }');
        await explorer.getByRole('button', { name: 'Run query', exact: true }).click();
        await expect(explorer.locator('.graph-node')).toHaveCount(5, { timeout: 30000 });
        await explorer.getByRole('button', { name: /Filter graph nodes/ }).click();
        const panel = explorer.locator('#graph-filter-sidebar');

        const born = panel.locator('.filter-facet', { hasText: 'birth date' });
        await expect(born, 'birthdays are a filter although none is loaded').toBeVisible({ timeout: 30000 });
        await expect(panel.locator('.filter-source')).toContainText('Values from the repository');
        await born.locator('summary').click();
        await born.getByLabel('birth date from').fill('1984-01-01');
        await born.getByLabel('birth date to').fill('1992-12-31');
        await expect(panel.locator('.filter-sidebar-header small')).toHaveText('3 of 5 nodes match');
        await expect(explorer.locator('.graph-node.is-selected')).toHaveCount(3);

        // Add RDF in another tab: this tab hears of the new data revision and loads the values again.
        const other = await context.newPage();
        await other.goto(repositoryPageUrl(id, 'add'));
        await waitForRoute(other, 'add');
        await other.locator('label[for="source-text"]').click();
        await other.locator('#text').fill('<http://example.org/people/ann> <http://example.org/people/colour> "green" .');
        await other.locator('#add-upload-actions input[type="submit"]').click();
        await expect(other.locator('.workbench-submit-status')).toContainText('Data added');
        await other.close();
        await expect(panel.locator('.filter-facet', { hasText: 'colour' })).toBeVisible({ timeout: 30000 });
    } finally {
        await deleteRepository(request, serverBaseUrl(), id);
    }
});
